// 규칙 점검 + 점수 (SEO·AEO·GEO) — 판정과 점수는 코드로 한다. LLM은 쓰지 않는다
const p = $json;
const url = $('Only Articles').item.json.loc;
const status = $('Fetch Article').item.json.statusCode;

const checks = [];
const add = (id, category, weight, result, message, value = null) =>
  checks.push({ id, category, weight, result, message, value });
const len = (s) => [...(s ?? '')].length;                 // 한글도 한 글자로 센다
const nonEmpty = (arr) => (arr ?? []).filter((v) => v && String(v).trim());

// ---------- SEO ----------
add('status', 'SEO', 3, status === 200 ? 'PASS' : 'FAIL', `HTTP ${status}`, status);

const noindex = /noindex/i.test(p.robots ?? '');
add('indexable', 'SEO', 3, noindex ? 'FAIL' : 'PASS', noindex ? 'noindex가 있어 검색에 안 나옴' : '색인 허용', p.robots ?? '');

const title = (p.title ?? '').replace(/ · 블로그스튜디오$/, '');   // 사이트 이름 꼬리는 빼고 잰다
const tl = len(title);
add('title', 'SEO', 1, tl === 0 ? 'FAIL' : tl >= 10 && tl <= 60 ? 'PASS' : 'WARN', tl === 0 ? '제목 없음' : `제목 ${tl}자 (권장 10~60자)`, title);

const dl = len(p.description);
add('description', 'SEO', 2, dl === 0 ? 'FAIL' : dl >= 50 && dl <= 160 ? 'PASS' : 'WARN', dl === 0 ? '메타 설명 없음' : `메타 설명 ${dl}자 (권장 50~160자)`);

const canonicalOk = (p.canonical ?? '').replace(/\/$/, '') === url.replace(/\/$/, '');
add('canonical', 'SEO', 2, canonicalOk ? 'PASS' : 'FAIL', canonicalOk ? '자기 주소를 가리킴' : p.canonical ? '다른 주소를 가리킴' : 'canonical 없음', p.canonical ?? '');

const h1s = nonEmpty(p.h1);
add('h1', 'SEO', 1, h1s.length === 1 ? 'PASS' : 'WARN', `h1 ${h1s.length}개`, h1s.length);

const ogMissing = ['ogTitle', 'ogDescription', 'ogImage'].filter((k) => !p[k]);
add('open-graph', 'SEO', 1, ogMissing.length ? 'WARN' : 'PASS', ogMissing.length ? `없음: ${ogMissing.join(', ')}` : 'og 태그 모두 있음');

let posting = null, ldError = false;                      // JSON-LD 여러 개 중 BlogPosting 찾기
for (const raw of p.jsonLd ?? []) {
  try {
    const obj = JSON.parse(raw);
    posting = posting ?? (obj['@graph'] ?? [obj]).find((n) => ['BlogPosting', 'Article'].includes(n['@type']));
  } catch { ldError = true; }
}
const ldMissing = posting ? ['headline', 'datePublished', 'author'].filter((k) => !posting[k]) : [];
add('json-ld', 'SEO', 2, ldError || !posting ? 'FAIL' : ldMissing.length ? 'WARN' : 'PASS',
  ldError ? 'JSON-LD 문법 오류' : !posting ? 'BlogPosting 없음' : ldMissing.length ? `빠진 필드: ${ldMissing.join(', ')}` : '필수 필드 있음');

// ---------- AEO ----------
const isQuestion = (s) => /\?|무엇|어떻게|왜|언제|어디|누가|얼마|(까|나요|가요|는가)\s*$/.test(s ?? '');
const headings = nonEmpty(p.headings);
const questions = [title, ...headings].filter(isQuestion);
add('question-heading', 'AEO', 1, questions.length ? 'PASS' : 'WARN', questions.length ? `질문형 제목·소제목 ${questions.length}개` : '질문형 제목·소제목 없음', questions[0] ?? '');

const paras = nonEmpty(p.paragraphs).map((s) => s.trim());
const first = paras.find((s) => len(s) >= 20) ?? '';     // 작성자 이름 같은 짧은 줄은 건너뜀
const fl = len(first);
add('answer-first', 'AEO', 2, fl >= 40 && fl <= 300 ? 'PASS' : 'WARN', fl === 0 ? '첫 문단 없음' : `첫 문단 ${fl}자 (권장 40~300자)`, first.slice(0, 80));

const longest = Math.max(0, ...paras.map(len));
add('paragraph-structure', 'AEO', 1, headings.length >= 2 && longest <= 800 ? 'PASS' : 'WARN', `소제목 ${headings.length}개, 가장 긴 문단 ${longest}자`);

// ---------- GEO ----------
const inHead = [p.titleInHead, p.descriptionInHead, p.canonicalInHead].filter(Boolean).length;
add('metadata-in-head', 'GEO', 2, inHead === 3 ? 'PASS' : 'WARN', inHead === 3 ? '메타데이터가 head 안에 있음' : `head 안에 있는 것 ${inHead}/3 — 나머지는 body로 스트리밍됨`);

const text = (p.bodyText ?? '').replace(/\[https?:\/\/[^\]]+\]/g, '');   // 이미지 주소 표시는 빼고 잰다
const textLen = len(text.replace(/\s+/g, ''));
add('ssr-text', 'GEO', 3, textLen >= 500 ? 'PASS' : textLen >= 200 ? 'WARN' : 'FAIL', `JS 없이 보이는 본문 ${textLen}자(공백 제외)`, textLen);

// Code 노드에서는 URL 을 쓸 수 없어 정규식으로 도메인을 꺼낸다
const hostOf = (u) => (String(u ?? '').match(/^(?:https?:)?\/\/([^/?#]+)/i) ?? [])[1] ?? '';
const host = hostOf(url);
// '/article/...' 같은 상대 주소는 도메인이 없으니 내부 링크로 본다
const external = nonEmpty(p.links).filter((h) => { const hh = hostOf(h); return hh && hh !== host; });
add('citations', 'GEO', 1, external.length ? 'PASS' : 'WARN', external.length ? `다른 사이트 링크 ${external.length}개` : '다른 사이트로 가는 링크 없음 — 출처가 약함', external.length);

const facts = (text.match(/\d+(?:[.,]\d+)?/g) ?? []).length;
add('concrete-facts', 'GEO', 1, facts >= 3 ? 'PASS' : 'WARN', `숫자·수치 ${facts}개`, facts);

// ---------- 점수: 가중치 × (PASS 1, WARN 0.5, FAIL 0) ----------
const score = (cat) => {
  const cs = checks.filter((c) => c.category === cat);
  const total = cs.reduce((s, c) => s + c.weight, 0);
  const got = cs.reduce((s, c) => s + c.weight * (c.result === 'PASS' ? 1 : c.result === 'WARN' ? 0.5 : 0), 0);
  return Math.round((got / total) * 100);
};

return {
  json: {
    url,
    title,
    scores: { seo: score('SEO'), aeo: score('AEO'), geo: score('GEO') },
    issueCount: checks.filter((c) => c.result !== 'PASS').length,
    checks,
    content: { title, description: p.description ?? '', headings, firstParagraph: first, text: text.slice(0, 3000) },
  },
};
